import{_ as t,o as i,c as a,aa as o}from"./chunks/framework.BAs_AphD.js";const n="/buildary-help-preview/media/en/tickets/en_btn_novy_ukol.png",r="/buildary-help-preview/media/en/tickets/en_novy_ukol.png",s="/buildary-help-preview/media/en/tickets/en_ukol_souvisejici_ukol.png",c="/buildary-help-preview/media/en/tickets/en_ukol_kopie.png",d="/buildary-help-preview/media/en/tickets/en_ukol_z_provedenych_praci.png",l="/buildary-help-preview/media/en/tickets/en_ukol_z_dalsich_zaznamu.png",h="/buildary-help-preview/media/en/tickets/en_souvisejici_ukoly.png",p="/buildary-help-preview/media/cs/tickets/ikona_ukol_z_deniku.png",g="/buildary-help-preview/media/cs/tickets/ikona_souvisejici_ukol.png",T=JSON.parse('{"title":"New Ticket","description":"","frontmatter":{"title":"New Ticket","wiki":"en:tickets:task_new"},"headers":[],"relativePath":"en/tickets/task_new.md","filePath":"en/tickets/task_new.md","lastUpdated":1794388980000}'),k={name:"en/tickets/task_new.md"};function m(u,e,w,b,f,y){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="new-ticket" tabindex="-1">New Ticket <a class="header-anchor" href="#new-ticket" aria-label="Permalink to &quot;New Ticket&quot;">​</a></h1><p>The basic way to create a ticket is to use the <img src="'+n+'" alt="New Ticket" width="100" data-no-zoom loading="lazy"> option on the left <strong>above the ticket grid in the Ticket List or above the Ticket Kanban</strong>. If this option is grayed out / inactive, the user does not have permission to create tickets.</p><p><strong>New Ticket Form:</strong></p><figure class="shot" style="--w:500px;"><img src="'+r+'" alt="New Ticket Form" width="480" loading="lazy"></figure><p>The new ticket form has a section collapsed by default, which is marked with a red frame in the image.</p><p>The ticket author enters the <strong>Subject</strong> - a concise and descriptive name for the ticket.</p><p><strong>Description</strong> - a space for a detailed description of the ticket, if needed.</p><p><strong>Category</strong> - the default categories can be modified by the administrator in Project Settings.</p><p><strong>Status</strong> - when creating a ticket, the following statuses are available: Draft / Not Started / In Progress / On Hold.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>In the Ticket Kanban</strong>, a ticket can be created using the <strong>+</strong> icon in the header of the Draft / Not Started / In Progress / On Hold columns. A ticket created this way has its <strong>status preselected</strong> according to the column from which the option was launched.</p></div><p>The author specifies the ticket <strong>priority</strong>.</p><p>A <strong>Label</strong> can be added if labels have been configured.</p><p><strong>Planned Dates</strong> - the start date is preset to the current date and the end date to +7 days. The author can change these dates.</p><p>The ticket can be <strong>localized on a drawing using markers or on the map</strong>. To do this, expand the <strong>Location and Drawings</strong> section using the corresponding icon to display the drawing selection field and map.</p><p>Drawings must be uploaded under Project Parts and Drawings to enable adding markers to them - LINK. Clicking a selected drawing opens an enlarged view, where markers can be placed by double-clicking the desired locations.</p><p>On the map, a marker can be placed by clicking the desired location or by entering an address in the Project Location field below the map.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>On the <strong>Drawings and Map</strong> page, a ticket can be created by double-clicking the desired location in the relevant drawing or on the map. A ticket created this way has a <strong>pre-filled drawing marker or map location</strong> at the point where the user double-clicked.</p></div><p><strong>Attachments</strong> - the author can attach photographs, documents, etc., if needed.</p><p><strong>Assignees and Approvers</strong> - the author specifies who should handle the ticket and who should approve it, selecting from users who are members of the Project Team. Multiple people can be selected.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>By defining <strong>Rules</strong> for Assignees / Approvers, these fields will be filled in automatically when the conditions of the ticket being created are met, with the option to modify them.</p></div><h3 id="new-related-ticket" tabindex="-1">New Related Ticket <a class="header-anchor" href="#new-related-ticket" aria-label="Permalink to &quot;New Related Ticket&quot;">​</a></h3><figure class="shot" style="--w:500px;"><img src="'+s+'" alt="Related Ticket" width="480" loading="lazy"></figure><p>Buildary provides the option to create a <strong>ticket linked to another ticket</strong>.</p><p>In the details of an existing ticket, selecting <strong>Create Related Ticket</strong> opens the New Ticket form with a link to the selected ticket. The link can be removed at the end of the form.</p><h2 id="new-ticket-by-copying-a-ticket" tabindex="-1">New Ticket by Copying a Ticket <a class="header-anchor" href="#new-ticket-by-copying-a-ticket" aria-label="Permalink to &quot;New Ticket by Copying a Ticket&quot;">​</a></h2><p><strong>1/ Copying the Last Created Ticket</strong> ⇒ the Copy Last Ticket option is available <strong>on the New Ticket page</strong> in the top-right corner, as shown in the New Ticket form above.</p><p>The new ticket will be pre-filled with data from the last created ticket (subject / category / selected drawing without markers / project location / assignees / approvers).</p><figure class="shot" style="--w:400px;"><img src="'+c+'" alt="Ticket Copy" width="200" loading="lazy"></figure><p><strong>2/ Copying a Ticket</strong> ⇒ <strong>in the details of an existing ticket</strong>, there is an option to Create a Copy of the Ticket.</p><p>With the exception of the status and label, all data is copied to the new ticket, including markers on the drawing and map, attachments, and dates. The author can edit everything as needed.</p><h2 id="new-ticket-from-a-project-diary-record" tabindex="-1">New Ticket from a Project Diary Record <a class="header-anchor" href="#new-ticket-from-a-project-diary-record" aria-label="Permalink to &quot;New Ticket from a Project Diary Record&quot;">​</a></h2><p>Users working with the Project Diary module can create tickets directly from diary records. The Ticket Management module must be enabled for the project.</p><p><strong>Tickets can be created from records in the Performed Works and Additional Records sections:</strong></p><img src="'+d+'" alt="Ticket from a Performed Works Record" width="500" loading="lazy"><img src="'+l+'" alt="Ticket from an Additional Record" width="500" loading="lazy"><h3 id="displaying-related-tickets" tabindex="-1">Displaying Related Tickets <a class="header-anchor" href="#displaying-related-tickets" aria-label="Permalink to &quot;Displaying Related Tickets&quot;">​</a></h3><figure class="shot" style="--w:500px;"><img src="'+h+'" alt="Related Tickets" width="480" loading="lazy"></figure><p>Tickets linked to diary records or other related tickets can be displayed in the Ticket List by <strong>adding the Related Tickets column</strong>.</p><p>The blue <img src="'+p+'" alt="Ticket Linked to Project Diary" width="50" data-no-zoom loading="lazy"> icon indicates a <strong>ticket linked to a Project Diary record</strong>. The icon is active and opens the relevant diary on the day containing the related record.</p><p>The orange <img src="'+g+'" alt="Related Tickets" width="50" data-no-zoom loading="lazy"> icon indicates a <strong>ticket linked to one or more other tickets</strong>. The number indicates the number of related tickets. The icon is active and opens the related ticket thread, from which the user can navigate to the details of the linked ticket.</p>',40)])])}const v=t(k,[["render",m]]);export{T as __pageData,v as default};
